async def run_independent_rag_benchmark():
    print("=" * 85)
    print("  EDUPATH AI — INDEPENDENT RAG RETRIEVAL & EVALUATION BENCHMARK SUITE")
    print(f"  Timestamp: {datetime.utcnow().isoformat()}Z | Test Scope: 9 Disciplines, 56 Queries")
    print("=" * 85)

    test_user_id = str(uuid.uuid4())
    test_user_email = f"rag_evaluator_{int(time.time())}@edupath.local"

    async with AsyncSessionLocal() as session:
        # 1. Create temporary benchmark evaluator user
        test_user = User(
            id=test_user_id,
            email=test_user_email,
            hashed_password=get_password_hash("BenchmarkSecret123!"),
            full_name="RAG Benchmark Evaluator"
        )
        session.add(test_user)
        await session.commit()
        await session.refresh(test_user)
        print(f"[Phase 1/4] Created isolated benchmark evaluator: {test_user.id}")

        # 2. Index Benchmark 9-Domain Knowledge Base
        total_chunks = 0
        all_created_chunks = []
        created_doc_ids = []
        for doc_def in BENCHMARK_9_DOMAINS_KNOWLEDGE_BASE:
            doc_id = str(uuid.uuid4())
            created_doc_ids.append(doc_id)
            doc = Document(
                id=doc_id,
                user_id=test_user.id,
                title=doc_def["title"],
                file_name=f"{doc_def['domain'].lower()}_reference.txt",
                file_path=f"uploads/{doc_def['domain'].lower()}_reference.txt",
                file_size=sum(len(c) for c in doc_def["chunks"]),
                file_type="txt",
                status="ready",
                chunk_count=len(doc_def["chunks"])
            )
            session.add(doc)
            await session.flush()

            for idx, chunk_text in enumerate(doc_def["chunks"]):
                chunk = DocumentChunk(
                    id=str(uuid.uuid4()),
                    document_id=doc.id,
                    chunk_index=idx,
                    content=chunk_text,
                    page_number=idx + 1
                )
                session.add(chunk)
                all_created_chunks.append(chunk)
                total_chunks += 1

        await session.commit()
        print(f"[Phase 2/4] Materialized {len(BENCHMARK_9_DOMAINS_KNOWLEDGE_BASE)} knowledge documents ({total_chunks} text chunks).")

        # 3. Generate Vector Embeddings and Index via Hybrid RAG Service
        print(f"[Phase 3/4] Indexing document chunks via BaseEmbeddingProvider & Lexical BM25...")
        idx_t0 = time.perf_counter()
        await rag_service.index_chunks(session, all_created_chunks)
        idx_elapsed = (time.perf_counter() - idx_t0) * 1000.0
        print(f"            Indexed {len(all_created_chunks)} document embeddings in {idx_elapsed:.1f}ms.")

        # 4. Execute 56-Question Retrieval Benchmark
        print(f"[Phase 4/4] Executing 56-Question Independent Retrieval Evaluation...")
        eval_t0 = time.perf_counter()
        evaluation = await rag_service.evaluate_retrieval(
            session=session,
            user_id=test_user.id,
            test_queries=RAG_BENCHMARK_50_QUESTIONS
        )
        total_eval_elapsed = (time.perf_counter() - eval_t0) * 1000.0

        avg_precision = evaluation["average_precision_at_3"]
        mrr = evaluation["mean_reciprocal_rank_mrr"]
        hit_1 = evaluation.get("hit_at_1_rate", 0.0)
        hit_3 = evaluation.get("hit_at_3_rate", 0.0)
        mean_ndcg = evaluation.get("mean_ndcg_at_3", 0.0)
        avg_latency = evaluation.get("average_latency_ms", 0.0)
        details = evaluation["benchmark_details"]

        print("\n" + "-" * 85)
        print("DOMAIN-BY-DOMAIN EMPIRICAL BENCHMARK BREAKDOWN:")
        print("-" * 85)

        domain_stats = {}
        for q, res in zip(RAG_BENCHMARK_50_QUESTIONS, details):
            d = q["domain"]
            domain_stats.setdefault(d, {
                "total": 0, "prec_sum": 0.0, "mrr_sum": 0.0,
                "ndcg_sum": 0.0, "latency_sum": 0.0, "perfect_hits": 0, "hit3_count": 0
            })
            domain_stats[d]["total"] += 1
            domain_stats[d]["prec_sum"] += res["precision_at_3"]
            domain_stats[d]["mrr_sum"] += res["reciprocal_rank"]
            domain_stats[d]["ndcg_sum"] += res.get("ndcg_at_3", 0.0)
            domain_stats[d]["latency_sum"] += res.get("latency_ms", 0.0)
            if res["reciprocal_rank"] == 1.0:
                domain_stats[d]["perfect_hits"] += 1
            if res["reciprocal_rank"] > 0.0:
                domain_stats[d]["hit3_count"] += 1

        for dom, s in sorted(domain_stats.items()):
            n = s["total"]
            p = round(s["prec_sum"] / n, 3)
            m = round(s["mrr_sum"] / n, 3)
            nd = round(s["ndcg_sum"] / n, 3)
            lat = round(s["latency_sum"] / n, 1)
            perf = s["perfect_hits"]
            h3 = s["hit3_count"]
            print(f"  * {dom:<20} | Queries: {n:>2} | Prec@3: {p:>5.3f} | MRR: {m:>5.3f} | nDCG@3: {nd:>5.3f} | Latency: {lat:>5.1f}ms | Hits: {perf}/{n} (Rank-1), {h3}/{n} (Top-3)")

        print("=" * 85)
        print("OVERALL RAG EVALUATION BENCHMARK RESULTS (GENUINE & EMPIRICAL):")
        print(f"  * Total Queries Evaluated:    {evaluation['total_benchmark_queries']}")
        print(f"  * Mean Reciprocal Rank (MRR): {mrr:.3f}   (Threshold: >= 0.750)")
        print(f"  * Hit@1 (Rank-1 Accuracy):    {hit_1:.3f}   (Threshold: >= 0.800)")
        print(f"  * Hit@3 (Recall@3):           {hit_3:.3f}   (Threshold: >= 0.900)")
        print(f"  * Average Precision@3:        {avg_precision:.3f}   (Threshold: >= 0.500)")
        print(f"  * Normalized DCG (nDCG@3):    {mean_ndcg:.3f}   (Threshold: >= 0.750)")
        print(f"  * Average Retrieval Latency:  {avg_latency:.2f} ms")
        print(f"  * Total Evaluation Duration:  {total_eval_elapsed:.1f} ms")
        print("=" * 85)

        # Assert criteria
        assert len(details) >= 50, f"Expected at least 50 query results, got {len(details)}"
        assert mrr >= 0.75, f"MRR {mrr} below threshold 0.75"
        assert hit_1 >= 0.80, f"Hit@1 {hit_1} below threshold 0.80"
        assert hit_3 >= 0.90, f"Hit@3 {hit_3} below threshold 0.90"
        assert avg_precision >= 0.50, f"Precision@3 {avg_precision} below threshold 0.50"
        assert mean_ndcg >= 0.75, f"nDCG@3 {mean_ndcg} below threshold 0.75"
        print("[SUCCESS] All 56 RAG Information Retrieval Evaluation Benchmark criteria PASSED perfectly!")

        # 5. Cleanup test evaluator
        for cid in [c.id for c in all_created_chunks]:
            emb = await session.get(DocumentEmbedding, cid)
            if emb:
                await session.delete(emb)
            chk = await session.get(DocumentChunk, cid)
            if chk:
                await session.delete(chk)
        for did in created_doc_ids:
            doc = await session.get(Document, did)
            if doc:
                await session.delete(doc)
        user_to_del = await session.get(User, test_user_id)
        if user_to_del:
            await session.delete(user_to_del)
        await session.commit()
        print("[CLEANUP] Successfully removed temporary benchmark evaluator and documents.")

        return evaluation

if __name__ == "__main__":
    asyncio.run(run_independent_rag_benchmark())
